package ar.org.inclusoft.api.attendance;
import java.time.*; import java.util.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import ar.org.inclusoft.api.user.UserRole;
@RestController @RequestMapping("/api/v1/attendance") class AttendanceController { private final AttendanceService service; AttendanceController(AttendanceService service){this.service=service;} @GetMapping("/workshops") @PreAuthorize("hasAnyRole('ADMIN','DIRECTOR','VICE_DIRECTOR','TEACHER')") List<AttendanceResponse> workshops(@RequestParam LocalDate date,Authentication auth){return service.findWorkshops(auth.getName(),role(auth),date);}@GetMapping("/workshops/{id}") @PreAuthorize("hasAnyRole('ADMIN','DIRECTOR','VICE_DIRECTOR','TEACHER')") AttendanceResponse find(@PathVariable UUID id,@RequestParam LocalDate date,Authentication auth){return service.find(auth.getName(),role(auth),id,date);}@PutMapping("/workshops/{id}") @PreAuthorize("hasAnyRole('ADMIN','DIRECTOR','VICE_DIRECTOR','TEACHER')") AttendanceResponse save(@PathVariable UUID id,@RequestParam LocalDate date,@Valid @RequestBody AttendanceRequest request,Authentication auth){return service.save(auth.getName(),role(auth),id,date,request);}@ExceptionHandler(AttendanceAccessException.class) ResponseEntity<Map<String,String>> bad(AttendanceAccessException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}private UserRole role(Authentication a){return a.getAuthorities().stream().map(x->x.getAuthority()).filter(x->x.startsWith("ROLE_")).findFirst().map(x->UserRole.valueOf(x.substring(5))).orElseThrow();}}
